#include <iostream>
#include <cstring>
#include <cctype>
#include <queue>
#include <functional>
#include <climits>
using namespace std;

const int dx[4] = {-1, 1, 0, 0};
const int dy[4] = {0, 0, -1, 1};
const int MAXN = 20;
const int MAXNODES = 1000;
const int MAXEDGES = 2000000;

struct Edge {
    int to, cap, rev;
};

vector<Edge> adj[MAXNODES];
int S, T, N, T_limit, INF_DIST;
int dist_map[MAXN][MAXN];
int depth_map[MAXN][MAXN];
int node_idx[MAXN][MAXN];
int sink_idx[MAXN][MAXN];
char grid_1[MAXN][MAXN];
char grid_2[MAXN][MAXN];

void connect(int u, int v, int cap) {
    adj[u].push_back({v, cap, (int)adj[v].size()});
    adj[v].push_back({u, 0, (int)adj[u].size() - 1});
}

void bfs(int sx, int sy, bool build) {
    queue<pair<int, int>> q;
    q.emplace(sx, sy);

    memset(dist_map, 0x3f, sizeof(dist_map));
    INF_DIST = dist_map[0][0];
    dist_map[sx][sy] = 0;

    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();

        if (build && sink_idx[x][y] && dist_map[x][y] <= T_limit && dist_map[x][y] <= depth_map[x][y]) {
            connect(node_idx[x][y], sink_idx[x][y], INF_DIST);
        }

        if (dist_map[x][y] > T_limit || dist_map[x][y] >= depth_map[x][y]) continue;

        if (node_idx[x][y] == 3 && sink_idx[x][y] == 9) {
            printf("%d\n", dist_map[x][y]);
        }

        for (int i = 0; i < 4; i++) {
            int nx = x + dx[i], ny = y + dy[i];
            if (nx >= 1 && nx <= N && ny >= 1 && ny <= N && isdigit(grid_1[nx][ny]) && dist_map[nx][ny] == INF_DIST) {
                dist_map[nx][ny] = dist_map[x][y] + 1;
                q.emplace(nx, ny);
            }
        }
    }
}

bool build_level() {
    static int level[MAXNODES];
    memset(level, 0, sizeof(level));
    queue<int> q;
    q.push(S);
    level[S] = 1;

    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (auto& e : adj[u]) {
            if (!level[e.to] && e.cap > 0) {
                level[e.to] = level[u] + 1;
                q.push(e.to);
                if (e.to == T) return true;
            }
        }
    }
    return false;
}

int dfs(int u, int flow) {
    if (u == T) return flow;
    for (auto& e : adj[u]) {
        if (e.cap > 0 && level[e.to] == level[u] + 1) {
            int pushed = dfs(e.to, min(flow, e.cap));
            if (pushed) {
                e.cap -= pushed;
                adj[e.to][e.rev].cap += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, t;
    cin >> n >> t;
    N = n;
    T_limit = t;

    for (int i = 1; i <= n; i++) {
        string s;
        cin >> s;
        for (int j = 0; j < n; j++) {
            grid_1[i][j+1] = s[j];
        }
    }

    for (int i = 1; i <= n; i++) {
        string s;
        cin >> s;
        for (int j = 0; j < n; j++) {
            grid_2[i][j+1] = s[j];
        }
    }

    memset(depth_map, 0x3f, sizeof(depth_map));
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (grid_1[i][j] == 'Z') {
                bfs(i, j, false);
            }
        }
    }
    memcpy(depth_map, dist_map, sizeof(dist_map));

    int node_count = 1;
    S = 0;
    T = 1;

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (grid_1[i][j] > '0' && grid_1[i][j] <= '9') {
                node_idx[i][j] = ++node_count;
                connect(S, node_idx[i][j], grid_1[i][j] - '0');
            }
            if (grid_2[i][j] > '0' && grid_2[i][j] <= '9') {
                sink_idx[i][j] = ++node_count;
                connect(sink_idx[i][j], T, grid_2[i][j] - '0');
            }
        }
    }

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (node_idx[i][j]) {
                bfs(i, j, true);
            }
        }
    }

    int max_flow = 0;
    while (build_level()) {
        while (int pushed = dfs(S, INF_DIST)) {
            max_flow += pushed;
        }
    }

    cout << max_flow << endl;
    return 0;
}
